-- public.event_rsvp_detail (staff only: names, statuses, notes)
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;

update public.profiles set display_name = 'Pat Ava' where id = 'a2222222-2222-2222-2222-222222222222';
-- Team A (club-linked, soccer): admin, coach, parents Ava/Ben, player Teen. Team B (basketball): coach B, parent Other.
-- Active on A: Ava, Ben, Teen. Inactive on A: Dan. Active on B: Cleo, Ivy (Ava's second team).

reset role;
reset role; set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select * from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') $$, '42501', null, 'anonymous users cannot call the detail');
reset role; select set_config('request.jwt.claims', '{"sub":"a1111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001')), 3, 'staff get every active rostered player');
select is((select string_agg(first_name || ' ' || last_name || ':' || coalesce(status, 'none'), ',' order by jersey_number) from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001')), 'Teen Adams:none,Ava Adams:going,Ben Brown:not_going', 'with full names, statuses and no-reply as null');
select is((select note from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') where first_name = 'Ava'), 'ava note', 'and notes');
select is((select responded_by_name from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') where first_name = 'Ava'), 'Pat Ava', 'and who responded');
select throws_ok($$ select * from public.event_rsvp_detail('e2000000-0000-0000-0000-00000000000b') $$, '42501', 'forbidden', 'staff cannot read another team''s detail');
reset role; select set_config('request.jwt.claims', '{"sub":"a8888888-8888-8888-8888-888888888888","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001')), 3, 'team admins can too');
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select * from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') $$, '42501', 'forbidden', 'a parent cannot read RSVP names');
reset role; select set_config('request.jwt.claims', '{"sub":"a7777777-7777-7777-7777-777777777777","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select * from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') $$, '42501', 'forbidden', 'a player cannot read RSVP names');
reset role; select set_config('request.jwt.claims', '{"sub":"a5555555-5555-5555-5555-555555555555","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select * from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') $$, '42501', 'forbidden', 'a club admin cannot read RSVP names');
reset role; select set_config('request.jwt.claims', '{"sub":"a4444444-4444-4444-4444-444444444444","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select * from public.event_rsvp_detail('e1000000-0000-0000-0000-000000000001') $$, '42501', 'forbidden', 'a parent on another team cannot either');
reset role; select set_config('request.jwt.claims', '{"sub":"a9999999-9999-9999-9999-999999999999","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select * from public.event_rsvp_detail('99999999-9999-9999-9999-999999999999') $$, '42501', 'forbidden', 'an unknown event looks the same as a forbidden one');
select * from finish();
rollback;
